const $=id=>document.getElementById(id),stage=$('stage'),cache=new Map();let manifest,runA,runB,scenes=[],pickables=[],playing=false,currentTime=0,lastTick=0,loadToken=0,selected=null;
const state={firstPerson:false};const headCameras=[0,1].map(()=>new THREE.PerspectiveCamera(85,1,.01,100));const palette={left:0x4f9aff,right:0xeea04c,vl:0x4f9aff,vr:0xeea04c,head:0x9bafc1,goal:0x63cfad,early:0xed779c,audit:0xe8ce6c,grab:0x96abc3,release:0xbba6df};
