const windowBounds=()=>[Number($('start').value),Number($('end').value)];const checked=id=>$(id).checked;const compare=()=>checked('compare');
function escape(s){const a=document.createElement('span');a.textContent=String(s);return a.innerHTML;}
function error(e){$('loading').style.display='grid';$('loading').textContent=e.message||String(e);console.error(e);}
async function fetchRun(id){if(cache.has(id))return cache.get(id);const r=await fetch('./data/'+encodeURIComponent(id)+'.json');if(!r.ok)throw Error('Recording could not load: '+id);const data=validateRun(await r.json());cache.set(id,data);return data;}
async function conditionRuns(cond){return Promise.all(manifest.runs.filter(r=>!r.repeat&&r.condition===cond).map(r=>fetchRun(r.id)));}
function initSelectors(){const ids=[...new Set(manifest.runs.map(r=>r.participant))].sort((a,b)=>Number(a.slice(1))-Number(b.slice(1)));for(const x of ['A','B']){$('participant'+x).innerHTML=ids.map(p=>`<option>${p}</option>`).join('');$('participant'+x).value=ids[0]||'';populateRuns(x,x==='A'?1:3);$('participant'+x).onchange=()=>{populateRuns(x);enforceComparison(x);load();};$('run'+x).onchange=()=>{enforceComparison(x);load();};}}
