function updateLabels(){stage.classList.toggle('split',compare());for(const [x,r]of [['A',runA],['B',runB]]){$('label'+x).innerHTML=`<strong>${x} / ${escape(r.participant)}</strong> · ${conditionName(r.condition)} <span>R${r.runIndex}${r.repeat?' · favourite/repeat':''} · ceiling ${r.limit}</span>`;}$('labelB').style.display=compare()?'block':'none';$('labelA').style.width=compare()?'50%':'100%';$('compareInputs').style.display=compare()?'block':'none';updatePanelLegends();}
function updatePanelLegends(){if(!runA)return;for(const [x,r]of [['A',runA],['B',runB]]){const el=$('panelLegend'+x);el.style.display=x==='B'&&!compare()?'none':'block';el.style.width=compare()?'50%':'100%';const mode=$('mode').value,parts=[];if(checked('leftHand'))parts.push('<i class="left"></i>Recorded left');if(checked('rightHand'))parts.push('<i class="right"></i>Recorded right');if(checked('physical'))parts.push('━━ Physical ('+$('physicalWidth').value+' px'+(checked('physicalForeground')?', foreground':'')+')');if(checked('virtual'))parts.push('┄┄ Virtual');if(checked('headDirection')&&!state.firstPerson)parts.push('<b class="cyan">➜</b> Head forward');if(checked('activityColour'))parts.push('Brightness: speed 0–100 cm/s');if(checked('factorHalo'))parts.push('Halo: factor 0–0.65');if(checked('predictionLayer'))parts.push('Purple: forecast top 3');if(checked('annotations'))parts.push('<b class="green">●</b> Goal · <b class="pink">●</b> Early release · <b class="yellow">●</b> Audit');const scope=mode==='density'&&$('heatSource').value==='group'?'Pooled main runs · '+conditionName(r.condition):mode==='targets'?'Main-run participants · '+conditionName(r.condition):r.participant+' · '+conditionName(r.condition)+' · R'+r.runIndex;if(state.firstPerson)parts.push('First person · head + '+$('headOffset').value+' cm · 85° vertical FOV');const audit=r.channelAudit;el.innerHTML=`<div class="legend-card"><strong>${x} / ${escape(scope)}</strong><div>${parts.join(' · ')}</div><small>${mode==='density'?'Density = hand-seconds / 10 cm voxel':mode==='targets'?'Colour/size = participant selection count':'Colours track channel identity, not screen side'}${checked('headDirection')?' · head ≠ eye gaze':''}</small>${mode==='trails'?`<small>Score ${r.score} · global O ${r.ratings?.ownership?.toFixed(2)||'—'} / A ${r.ratings?.agency?.toFixed(2)||'—'}</small>`:''}<small id="panelForecast${x}"></small></div>`;}}
function disposeScene(s){s.traverse(o=>{if(o.geometry)o.geometry.dispose();if(o.material){const ms=Array.isArray(o.material)?o.material:[o.material];for(const m of ms)m.dispose();}});}
function addLine(scene,points,color,dashed=false,opacity=1){if(points.length<2)return;const geo=new THREE.BufferGeometry().setFromPoints(points.map(p=>new THREE.Vector3(...p)));const mat=dashed?new THREE.LineDashedMaterial({color,dashSize:.035,gapSize:.025,transparent:true,opacity}):new THREE.LineBasicMaterial({color,transparent:true,opacity});const line=new THREE.Line(geo,mat);if(dashed)line.computeLineDistances();scene.add(line);return line;}
function sphere(scene,p,color,radius=.035,data){const mesh=new THREE.Mesh(new THREE.SphereGeometry(radius,12,8),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.95}));mesh.position.set(...p);scene.add(mesh);if(data){mesh.userData=data;pickables.push(mesh);}return mesh;}
function baseScene(){const scene=new THREE.Scene();scene.background=new THREE.Color(checked('paper')?0xffffff:0x101b2a);const grid=new THREE.GridHelper(8,16,checked('paper')?0xa8b5c2:0x3b5268,checked('paper')?0xdce3e9:0x24364a);scene.add(grid);const axes=new THREE.AxesHelper(.6);axes.position.set(-2.7,.01,2.7);scene.add(axes);return scene;}
function keys(){return [...(checked('physical')?['left','right']:[]),...(checked('virtual')?['vl','vr']:[])].filter(k=>(k==='left'||k==='vl')?checked('leftHand'):checked('rightHand'));}
function directionAt(run,key,time){const i=Math.min(run.times.length-1,Math.max(0,Math.round(time*run.sampleHz)));return time<=run.duration+.1?run.headDirections?.[key]?.[i]||null:null;}
function headRayPoints(p,f,right,up){const v=new THREE.Vector3(...p),F=new THREE.Vector3(...f),R=new THREE.Vector3(...right),U=new THREE.Vector3(...up),tip=v.clone().addScaledVector(F,.34);return [[v.toArray(),tip.toArray()],...[-1,1].map(sign=>[tip.toArray(),tip.clone().addScaledVector(F,-.08).addScaledVector(R,.045*sign).toArray()]),[v.toArray(),v.clone().addScaledVector(R,-.12).toArray()],[v.toArray(),v.clone().addScaledVector(R,.12).toArray()],[v.toArray(),v.clone().addScaledVector(U,.13).toArray()]];}
