if(checked('annotations'))for(const event of run.events){if(event.t<from||event.t>end)continue;sphere(scene,transformPosition(event.position,run,align),palette[event.type]||0xbbcddd,event.type==='early'||event.type==='audit'?.047:.032,{kind:'event',event,run,view:n});}
