$('exportData').onclick=()=>{const rs=compare()?[runA,runB]:[runA];const view={alignment:$('alignment').value,window:windowBounds(),cameraPosition:camera.position.toArray(),target:controls.target.toArray(),firstPerson:state.firstPerson,headForwardOffsetCm:Number($('headOffset').value),firstPersonVerticalFov:85,orthographic:!state.firstPerson&&checked('ortho'),zoom:camera.zoom,physicalTrailWidth:Number($('physicalWidth').value),time:currentTime,fullTrails:checked('fullTrails'),mode:$('mode').value,factorScale:$('factorScale').value,heatSource:$('heatSource').value,targetMetric:$('targetMetric').value,layers:Object.fromEntries(['physical','virtual','leftHand','rightHand','objects','annotations','links','targets','headDirection','headHistory','activityColour','factorHalo','predictionLayer','physicalForeground'].map(id=>[id,checked(id)])),forecastCase:state.activeForecastCase||null};const data=rs.length===1?{...rs[0],coordinateSystem:manifest.coordinateSystem,view}:{schema:'vr-motion-atlas-bundle/1',coordinateSystem:manifest.coordinateSystem,view,runs:rs};download(new Blob([JSON.stringify(data)],{type:'application/json'}),rs.length===1?runA.id+'.json':'motion-atlas-comparison.json');};
