$('importData').onchange=async e=>{try{const data=JSON.parse(await e.target.files[0].text());const rs=data.schema==='vr-motion-atlas-bundle/1'?data.runs:[data];for(const input of rs){const r=validateRun(input);if(!r.participant||!r.condition||!r.sampleHz)throw Error('Participant, condition and sampleHz are required.');cache.set(r.id,r);if(!manifest.runs.some(x=>x.id===r.id))manifest.runs.push({id:r.id,participant:r.participant,condition:r.condition,runIndex:r.runIndex||99,repeat:!!r.repeat});}initSelectors();for(const [i,x]of ['A','B'].entries()){const r=rs[Math.min(i,rs.length-1)];$('participant'+x).value=r.participant;populateRuns(x);$('run'+x).value=r.id;}await load();}catch(e){error(e);}};
